sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api}) {

  const roles = api.context.session.user.roles || [];

  if (roles.includes('x_1909965_almaconn.admin')) {
    api.navigation.navigate('/x/1909965/admin-portal/dashboard');
    return;
  }

  if (roles.includes('x_1909965_almaconn.alumni_user')) {
    api.navigation.navigate('/x/1909965/alumni-portal/dashboard');
    return;
  }

  if (roles.includes('x_1909965_almaconn.Student')) {
    api.navigation.navigate('/x/1909965/almaconnect/dashboard');
    return;
  }

}
